// spec: specs/authz-isolation.md (1.2) · кейсы AZ-02, AZ-03 · две роли (parent, parent-b) — пишет autotest-writer
// Контроль: владелец видит своего ребёнка. Чужая семья: чтение = как для несуществующего id ([] или 403), без имени;
// PATCH чужого (тем же именем) → 0 строк; INSERT в чужую семью → 403. DELETE не выполняется.
// Дополняет SA-04 (parent-b → семья A: children, writing_attempts, current_levels, child_profile, next_activity).
import { test, expect } from '../../fixtures';
import { NONEXISTENT_CHILD, captureSupabase } from '../session-auth/session-auth.helpers';
import { api, QA_B1, QA_R2_1, randomLetters } from './authz.helpers';

test.use({ viewport: { width: 1280, height: 800 } });

type Probe = { label: string; method: 'GET' | 'POST'; path: (id: string) => string; body?: (id: string) => unknown };

const READS: Record<string, Probe> = {
  children: { label: 'children', method: 'GET', path: (id) => `/rest/v1/children?id=eq.${id}&select=id,nickname` },
  reading_attempts: { label: 'reading_attempts', method: 'GET', path: (id) => `/rest/v1/reading_attempts?child_id=eq.${id}&select=id` },
  writing_attempts: { label: 'writing_attempts', method: 'GET', path: (id) => `/rest/v1/writing_attempts?child_id=eq.${id}&select=id` },
  skill_levels: { label: 'skill_levels', method: 'GET', path: (id) => `/rest/v1/skill_levels?child_id=eq.${id}&select=*` },
  child_profile: { label: 'rpc/child_profile', method: 'POST', path: () => '/rest/v1/rpc/child_profile', body: (id) => ({ p_child_id: id }) },
  current_levels: { label: 'rpc/current_levels', method: 'POST', path: () => '/rest/v1/rpc/current_levels', body: (id) => ({ p_child_id: id }) },
};

test('REST к чужим детям в обе стороны = как к несуществующему; запись в чужую семью отклонена @desktop #25b101', async ({ asUser }, testInfo) => {
  const parentA = await asUser('parent');
  const parentB = await asUser('parent-b');
  const sbA = await captureSupabase(parentA, '/children');
  const sbB = await captureSupabase(parentB, '/children');

  // 1) Контроль: владельцы видят своих детей (иначе проверка изоляции пустая)
  const ownB = await api(parentB.request, sbB, 'GET', `/rest/v1/children?id=eq.${QA_B1}&select=id,nickname,family_id`);
  expect(ownB.status, ownB.text).toBe(200);
  const b1 = JSON.parse(ownB.text) as { id: string; nickname: string; family_id: string }[];
  expect(b1.map((c) => c.nickname), 'parent-b видит QA-B1').toEqual(['QA-B1']);
  // TODO verify: имя колонки семьи в children (family_id) — при первом /qa-regress
  const familyB = b1[0].family_id;
  expect(familyB, 'family_id семьи B').toBeTruthy();

  const ownA = await api(parentA.request, sbA, 'GET', `/rest/v1/children?id=eq.${QA_R2_1}&select=id,nickname`);
  expect(JSON.parse(ownA.text).map((c: { nickname: string }) => c.nickname), 'parent видит QA-R2-1').toEqual(['QA-R2-1']);

  // 2) parent → QA-B1 (семья B) и → несуществующий: одинаковые ответы, без имени
  const checkSame = async (page: typeof parentA, sb: typeof sbA, probe: Probe, foreignId: string, foreignName: string) => {
    const f = await api(page.request, sb, probe.method, probe.path(foreignId), probe.body?.(foreignId));
    const m = await api(page.request, sb, probe.method, probe.path(NONEXISTENT_CHILD), probe.body?.(NONEXISTENT_CHILD));
    expect.soft(f.status, `${probe.label}: чужой ${f.text}`).toBe(m.status);
    expect.soft(f.text, `${probe.label}: тело для чужого = для несуществующего (AC2)`).toBe(m.text);
    expect.soft([200, 403], `${probe.label}: код ${f.status}`).toContain(f.status);
    if (f.status === 200) expect.soft(f.text.trim(), `${probe.label}: пусто`).toBe('[]');
    expect.soft(f.text, `${probe.label}: нет имени чужого ребёнка`).not.toContain(foreignName);
  };
  for (const p of Object.values(READS)) await checkSame(parentA, sbA, p, QA_B1, 'QA-B1');

  const allA = await api(parentA.request, sbA, 'GET', '/rest/v1/children?select=id');
  expect(allA.status, allA.text).toBe(200);
  expect(allA.text, 'children без фильтра у parent не содержит QA-B1 (AC1)').not.toContain(QA_B1);

  // 3) parent-b → QA-R2-1: таблицы, которых нет в SA-04
  for (const p of [READS.reading_attempts, READS.skill_levels]) await checkSame(parentB, sbB, p, QA_R2_1, 'QA-R2-1');

  // 4) Запись в чужую семью токеном parent
  const patch = await api(parentA.request, sbA, 'PATCH', `/rest/v1/children?id=eq.${QA_B1}`, { nickname: 'QA-B1' }, { Prefer: 'return=representation' });
  if (patch.status === 200) expect.soft(patch.text.trim(), 'PATCH чужого → 0 строк').toBe('[]');
  else expect.soft([401, 403, 404], `PATCH чужого: ${patch.status} ${patch.text}`).toContain(patch.status);

  const name = `QA-AUTO-${randomLetters()}`;
  const insert = await api(parentA.request, sbA, 'POST', '/rest/v1/children', { nickname: name, birth_year: 2018, family_id: familyB }, { Prefer: 'return=representation' });
  if (insert.status < 300) {
    testInfo.annotations.push({ type: 'cleanup', description: `child ${name} в семье parent-b (${insert.text}) — удалить вручную` });
  }
  expect.soft(insert.status, `INSERT в семью B: ${insert.text}`).toBe(403);
});
